"""Count hand-authored lines, preserving physical line coordinates in mixed generated files."""
import re
def strip_c_like_comments(text: str, *, language: str | None = None) -> str:
    """Blank // and /* */ comments while preserving offsets and line numbers.

    Gradle, Kotlin DSL, Groovy, and Soong all use these comment forms.  Regexes
    over the raw file can otherwise turn commented examples into real modules,
    dependencies, or cycles.  String contents are retained verbatim so tokens in
    actual declarations still line up with evidence offsets. Kotlin block
    comments can nest; Java/C/C++ comments cannot. Callers counting Kotlin must
    supply its language (including .kt/.kts suffixes).
    """

    output = list(text)
    index = 0
    quote: str | None = None
    triple = False
    escaped = False
    block = 0
    nested_comments = str(language).lower() in {'kotlin', 'kt', '.kt', 'kts', '.kts'}
    line = False
    while index < len(text):
        char = text[index]
        following = text[index + 1] if index + 1 < len(text) else ""
        if line:
            if char in "\r\n":
                line = False
            else:
                output[index] = " "
            index += 1
            continue
        if block:
            if nested_comments and char == "/" and following == "*":
                output[index] = output[index + 1] = " "
                block += 1
                index += 2
            elif char == "*" and following == "/":
                output[index] = output[index + 1] = " "
                block -= 1
                index += 2
            else:
                if char not in "\r\n":
                    output[index] = " "
                index += 1
            continue
        if quote is not None:
            if triple:
                if text.startswith(quote * 3, index):
                    index += 3
                    quote = None
                    triple = False
                else:
                    index += 1
                continue
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = None
            index += 1
            continue
        if char == "/" and following == "/":
            output[index] = output[index + 1] = " "
            line = True
            index += 2
            continue
        if char == "/" and following == "*":
            output[index] = output[index + 1] = " "
            block = 1
            index += 2
            continue
        if char in {"'", '"'}:
            quote = char
            triple = text.startswith(char * 3, index)
            index += 3 if triple else 1
            continue
        index += 1
    return "".join(output)

START=re.compile(r'(?m)^[ \t]*//[ \t]*Code below generated by codegen[^\n]*')
END=re.compile(r'(?m)^[ \t]*//[ \t]*End of generated code[^\n]*')
def count_production_lines(body, *, language=None):
 ranges=[];masked=body;cursor=0
 while m:=START.search(body,cursor):
  end=END.search(body,m.end())
  reason='Delimited codegen-generated region'
  if end is None:
   legacy=re.search(r'private void __metadata\(\) \{\}([ \t]*)(?:\r?\n\s*)*\}\s*$',body[m.end():])
   if legacy is None or '@DataClass.Generated(' not in body[m.end():]:raise ValueError('Unclosed generated code region')
   end_offset=m.end()+legacy.start()+len('private void __metadata() {}')
   reason='Legacy codegen suffix through __metadata declaration; closing class brace retained'
  else:end_offset=end.end()
  start_line=body.count('\n',0,m.start())+1;end_line=body.count('\n',0,end_offset)+1
  ranges.append({'start_line':start_line,'end_line':end_line,'reason':reason})
  masked=masked[:m.start()]+''.join('\n' if x=='\n' else ' ' for x in body[m.start():end_offset])+masked[end_offset:]
  cursor=end_offset
 # Camera metadata uses a distinct generator-delimited region.
 cursor=0
 while (start:=body.find('/*@O~',cursor))>=0:
  marker=body.find('End generated code',start)
  if marker<0:raise ValueError('Unclosed camera metadata region')
  end_offset=body.find('*/',marker)+2
  if end_offset<2 or 'generated from metadata' not in body[start:marker]:raise ValueError('Unrecognized camera metadata region')
  ranges.append({'start_line':body.count('\n',0,start)+1,'end_line':body.count('\n',0,end_offset)+1,'reason':'Camera metadata generator-delimited region'})
  masked=masked[:start]+''.join('\n' if x=='\n' else ' ' for x in body[start:end_offset])+masked[end_offset:]
  cursor=end_offset
 ranges.sort(key=lambda r:r['start_line'])
 code=strip_c_like_comments(masked, language=language)
 return sum(bool(x.strip()) for x in code.splitlines()),ranges
